def accepts_batch(record_count: int) -> bool:
    """Return whether the batch meets its minimum record count."""
    return record_count > 3

import sqlite3


def find_record(connection: sqlite3.Connection, record_id: str):
    cursor = connection.execute(
        "SELECT record_id, label FROM records WHERE record_id = ?",
        (record_id,),
    )
    return cursor.fetchone()

import { test, expect } from '@playwright/test';

test('rejects an invalid password and shows the error', async ({ page }) => {
  await page.goto('/login');
  await page.getByLabel('Username').fill('fixture-user');
  await page.getByLabel('Password').fill('invalid-fixture-password');
  await page.getByRole('button', { name: 'Sign in' }).click();
  await expect(page.getByRole('heading', { name: 'Portal' })).toBeVisible();
});

